#!/usr/bin/env bash
# Sample TPG source for the `dev` profile (US-003, US-040): synthetic data only, never client data.
# * tela_ro: the read-only login Tela is given (SELECT on the extract tables, nothing else).
# The data file 02-data.sql is generated by deploy/compose/dev-setup.sh from packs/pmo/fixtures/tpg_synthetic.py.
set -euo pipefail
ro_pw="$(cat /run/secrets/sample_tpg_ro_password)"
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" -v ro_pw="$ro_pw" <<'SQL'
CREATE ROLE tela_ro LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE PASSWORD :'ro_pw';
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
SQL
